export interface GiftResponse {
    quantity: number;
    product: Product;
    sender_name: string;
    gift_images: GiftImage[];
    gift_texts: GiftText[];
    cities?: Cities[];
    countries?: Country[];
    enable_scopes?: boolean;
    show_custom_text?: boolean;
    show_image_upload?: boolean;
    show_images?: boolean;
    show_texts?: boolean;
    recipient_can_change_address?: boolean;
    allows_different_shipping_cost?: boolean;
}
export interface Cities {
    id: number;
    name: string;
}
export interface Region {
    id: number;
    name: string;
}
export interface Country {
    id: number;
    name: string;
    country_code: string;
}
export interface Product {
    id: number;
    name: string;
    type: string;
}
export interface GiftImage {
    id: number;
    url: string;
}
export interface GiftText {
    id: number;
    text: string;
}
